<template><view class="quality-card"><view class="quality-heading"><text>发布资料检查</text><text class="quality-count">{{ checks.filter(item=>item.ok).length }} / {{ checks.length }}</text></view><view class="quality-grid"><view v-for="item in checks" :key="item.code" class="quality-item" :class="{done:item.ok}"><text class="quality-dot">{{ item.ok?'✓':item.required?'○':'·' }}</text><text>{{ item.label }}</text></view></view><text class="quality-note">资料检查会随填写自动更新；建议项不阻止发布，服务端仍会核验图片归属和风险文本。</text><button class="quality-button" :disabled="disabled || checking || !currentUser || checks.some(item=>item.required&&!item.ok)" @click="check">{{ checking?'正在检查…':'检查图片归属与文本规则' }}</button><text v-if="error" class="quality-error">{{ error }}</text><text v-if="result" class="quality-note">{{ result.notice }}</text><text v-for="advice in result?.suggestions || []" :key="advice.code" class="quality-note">· {{ advice.message }}</text></view></template>
<script setup>
import {computed,ref,watch,onUnmounted} from 'vue'
import {currentUser,getToken} from '@/utils/session.js'
import {localProductChecks} from '@/utils/platform.mjs'
import {productQuality} from '@/api/platform.js'
const props=defineProps({draft:{type:Object,required:true},active:Boolean,disabled:Boolean}),checking=ref(false),result=ref(null),error=ref(''),checks=computed(()=>localProductChecks(props.draft))
let generation=0,disposed=false
watch(()=>[props.draft,currentUser.value?.id,getToken(),props.active],()=>{generation++;result.value=null;error.value='';checking.value=false},{deep:true,flush:'sync'})
async function check(){if(disposed||!props.active||checking.value||props.disabled||!currentUser.value)return;const turn=++generation,token=getToken(),user=currentUser.value.id,draft=props.draft;checking.value=true;error.value='';result.value=null
 try{const value=await productQuality({title:draft.title,description:draft.description,priceInCents:Math.round(Number(draft.priceText)*100),categoryCode:draft.categoryCode,coverImageId:draft.coverImageId,details:draft.details});if(disposed||!props.active||turn!==generation||token!==getToken()||user!==currentUser.value?.id)return;if(value?.canPublish!==true||!Array.isArray(value.suggestions)||value.suggestions.length>5||typeof value.notice!=='string'||value.suggestions.some(item=>typeof item.code!=='string'||typeof item.message!=='string'))throw new Error('检查结果不完整');result.value=value}
 catch(failure){if(!disposed&&props.active&&turn===generation&&token===getToken()&&user===currentUser.value?.id)error.value=failure.message||'检查失败，请重试'}finally{if(turn===generation)checking.value=false}}
onUnmounted(()=>{disposed=true;generation++;result.value=null;error.value=''})
</script>
<style scoped>.quality-card{padding:20px;border:1px solid #dfe9fa;border-radius:14px;background:#f8fbff;margin:22px 0;color:#49678e}.quality-heading{display:flex;justify-content:space-between;font-size:14px;font-weight:650}.quality-count{font-size:12px;color:#86a0c5}.quality-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px 18px;margin:18px 0}.quality-item{display:flex;gap:8px;color:#91a1b9;font-size:12px;line-height:1.8}.quality-item.done{color:#3d7d69}.quality-dot{flex-shrink:0}.quality-note{display:block;color:#8497b4;font-size:11px;line-height:1.9;margin-top:7px}.quality-button{font-size:12px;min-height:40px;line-height:38px;border-radius:9px;border:1px solid #d2e0f5;background:white;color:#3d6bb0;margin:16px 0 0}.quality-button:after{border:0}.quality-error{display:block;font-size:12px;color:#b42318;margin-top:12px;line-height:1.8}@media(max-width:600px){.quality-card{padding:17px}.quality-grid{grid-template-columns:1fr;gap:8px}}</style>
